import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Host concepts","description":"","frontmatter":{},"headers":[],"relativePath":"handl/reference/host-concepts.md","filePath":"vendored/handl/reference/host-concepts.md"}`),a={name:`handl/reference/host-concepts.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="host-concepts" tabindex="-1">Host concepts <a class="header-anchor" href="#host-concepts" aria-label="Permalink to “Host concepts”">​</a></h1><p>This reference describes the core types, traits, and components that make up a composable host. It is intended to be read while working with the <code>handl-platform</code> API.</p><h2 id="traits" tabindex="-1">Traits <a class="header-anchor" href="#traits" aria-label="Permalink to “Traits”">​</a></h2><table tabindex="0"><thead><tr><th>Trait</th><th>Role</th></tr></thead><tbody><tr><td><code>Plugin</code></td><td>The universal, object-safe base trait. Every loaded component implements this.</td></tr><tr><td><code>RuleAcceptor</code></td><td>A sub-trait of <code>Plugin</code> for components that accept contributions. <code>RuleAcceptor::Rule</code> is the associated contribution type.</td></tr><tr><td><code>Operation</code></td><td>A marker trait for a cross-cutting concern such as <code>Format</code>, <code>Lint</code>, or <code>Cli</code>.</td></tr><tr><td><code>Behavior&lt;Op&gt;</code></td><td>A rule that contributes to a specific <code>Operation</code> for a specific <code>AstNode.kind</code>.</td></tr><tr><td><code>Host</code></td><td>The composer that owns the <code>PluginRegistry</code> and drives loading.</td></tr><tr><td><code>HostApplier</code></td><td>Reads external configuration and applies it to a <code>Host</code> as a <code>HostConfig</code>.</td></tr><tr><td><code>Contribution</code></td><td>Base trait for rules such as <code>OptionSchema</code> and <code>DataType</code>.</td></tr></tbody></table><h2 id="core-types" tabindex="-1">Core types <a class="header-anchor" href="#core-types" aria-label="Permalink to “Core types”">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>PluginRegistry</code></td><td>Stores <code>Box&lt;dyn Plugin&gt;</code> and resolves capabilities and dependencies.</td></tr><tr><td><code>ContributionContext</code></td><td>Passed to <code>Plugin::contribute</code>. Provides <code>register_plugin</code> and <code>contribute::&lt;P: RuleAcceptor&gt;(rule)</code>.</td></tr><tr><td><code>PluginContext</code></td><td>Passed to <code>Plugin::run</code>. Gives the plugin access to the host while running a capability.</td></tr><tr><td><code>CapabilityRequest</code></td><td>A request to execute a capability, carrying the capability id and a JSON payload.</td></tr><tr><td><code>CapabilityResponse</code></td><td>The result of executing a capability.</td></tr><tr><td><code>CapabilityId</code></td><td>The string identifier for a capability.</td></tr><tr><td><code>AstNode</code></td><td>A generic AST node with <code>kind</code>, <code>span</code>, and <code>payload</code>.</td></tr><tr><td><code>Kit</code></td><td>A manifest of plugins to load, plus metadata.</td></tr><tr><td><code>KitManifest</code></td><td>The on-disk or embedded TOML manifest for a kit.</td></tr><tr><td><code>HostConfig</code></td><td>In-memory description of kits to load, plugins to include or exclude, and option overrides.</td></tr><tr><td><code>OptionSchema</code></td><td>A plugin-contributed option definition with id, scope, default, and allowed values.</td></tr><tr><td><code>ResolvedOptions</code></td><td>The merged and validated option values available during <code>run</code> and <code>Behavior::apply</code>.</td></tr><tr><td><code>DataType</code></td><td>A plugin-contributed runtime data type.</td></tr></tbody></table><h2 id="plugin-lifecycle" tabindex="-1">Plugin lifecycle <a class="header-anchor" href="#plugin-lifecycle" aria-label="Permalink to “Plugin lifecycle”">​</a></h2><ol><li><strong>Register</strong> — plugins are added to <code>PluginRegistry</code> from kits, direct registration, or another plugin&#39;s <code>contribute</code>.</li><li><strong>Resolve dependencies</strong> — the host topologically sorts plugins by <code>requires</code> and <code>optional</code>.</li><li><strong>Contribute</strong> — <code>Plugin::contribute</code> is called for each plugin, passing a <code>ContributionContext</code>.</li><li><strong>Fixed point</strong> — if a <code>contribute</code> step registers new plugins, the host returns to step 2 until no new plugins appear.</li><li><strong>Resolve options</strong> — the <code>Options</code> plugin merges defaults, kit, host, and user values and validates them.</li><li><strong>Run</strong> — <code>Host::execute</code> dispatches a <code>CapabilityRequest</code> to the plugin that provides the requested capability.</li></ol><h2 id="operation-categories" tabindex="-1">Operation categories <a class="header-anchor" href="#operation-categories" aria-label="Permalink to “Operation categories”">​</a></h2><p><code>handl-platform</code> ships the built-in operation contracts; each <code>handl-plugin-ext-*</code> crate is the published capability surface that wires the contract into the capability system. The engines behind the contracts live in the <code>engine-*</code> repos where published.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Contract</th><th><code>RuleAcceptor</code></th><th>Engine repo</th></tr></thead><tbody><tr><td><code>Format</code></td><td><code>handl-platform::Format</code></td><td><code>BasicFormatter</code> accepts <code>Behavior&lt;Format&gt;</code></td><td><em>(not yet published)</em></td></tr><tr><td><code>Lint</code></td><td><code>handl-platform::Lint</code></td><td><code>BasicLinter</code> accepts <code>Behavior&lt;Lint&gt;</code></td><td><em>(not yet published)</em></td></tr><tr><td><code>Compile</code></td><td><code>handl-platform::Compile</code></td><td><code>BasicCompiler</code> accepts <code>Behavior&lt;Compile&gt;</code></td><td><em>(not yet published)</em></td></tr><tr><td><code>Eval</code></td><td><code>handl-platform::Eval</code></td><td><code>BasicEvaluator</code> accepts <code>Behavior&lt;Eval&gt;</code></td><td><code>hnl-engine-exec</code>, <code>hnl-engine-exec-tree-walk</code></td></tr><tr><td><code>Options</code></td><td><code>handl-platform</code></td><td><code>OptionsPlugin</code> accepts <code>OptionSchema</code> rules</td><td>built into the platform</td></tr></tbody></table><p>Further operation contracts — <code>diag</code>, <code>detect</code>, <code>kit</code>, <code>plugin</code>, <code>refinement</code>, <code>sdkgen</code>, <code>test</code>, <code>typecheck</code> — are published as <code>handl-plugin-ext-*</code> crates in the <a href="https://github.com/handl-lang/host" target="_blank" rel="noreferrer"><code>host</code> repo</a>. The lex/parse/transform engine abstractions are <code>hnl-engine-lex</code>, <code>hnl-engine-parse</code>, and <code>hnl-engine-transform</code>.</p><h2 id="common-plugin-kinds" tabindex="-1">Common plugin kinds <a class="header-anchor" href="#common-plugin-kinds" aria-label="Permalink to “Common plugin kinds”">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>What it does in <code>contribute</code></th></tr></thead><tbody><tr><td>Library plugin</td><td>Calls <code>ContributionContext::register_plugin</code> to load more plugins.</td></tr><tr><td>Target plugin</td><td>Registers target-specific operations and contributes <code>OptionSchema</code> values.</td></tr><tr><td>Rule plugin</td><td>Calls <code>ContributionContext::contribute::&lt;P&gt;(rule)</code> to add a rule to an existing <code>RuleAcceptor</code>.</td></tr><tr><td>Operation plugin</td><td>Accepts rules and executes them when a capability is requested.</td></tr><tr><td>Executable host</td><td>Loads kits, applies config, and calls <code>Host::execute</code> for <code>Cli</code> or <code>Lsp</code>.</td></tr></tbody></table>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};